"""Exact keep-rate audit: enumerate the residue model and compare real, sham and the law."""
from __future__ import annotations
import math
import random
from typing import Callable, Dict, List, Set


def units(m: int) -> List[int]:
    return [x for x in range(1, m) if math.gcd(x, m) == 1]


Policy = Dict[int, Set[int]]


def hit_count(G: List[int], m: int, K: Policy) -> int:
    return sum(1 for a in G for b in G if a in K[(a * b) % m])


def sym_hit_count(G: List[int], m: int, K: Policy) -> int:
    return sum(1 for a in G for b in G if a in K[(a * b) % m] or b in K[(a * b) % m])


def sham_of(K: Policy, G: List[int], rng: random.Random) -> Policy:
    return {c: set(rng.sample(G, len(K[c]))) for c in K}


def audit(m: int, K: Policy, seed: int = 0, shams: int = 20) -> Dict[str, object]:
    rng = random.Random(seed)
    G = units(m)
    law = sum(len(K[c]) for c in G)
    real = hit_count(G, m, K)
    sham_scores = [hit_count(G, m, sham_of(K, G, rng)) for _ in range(shams)]
    return {
        "n": len(G), "law": law, "real": real, "shams": sorted(set(sham_scores)),
        "real_equals_sham": all(s == real for s in sham_scores) and real == law,
        "unordered_real": sym_hit_count(G, m, K),
    }


if __name__ == "__main__":
    m = 28
    G = units(m)
    K = {c: set(sorted(G, key=lambda x: (c * pow(x, -1, m)) % m)[:4]) for c in G}
    print(audit(m, K))

"""Two diagnostics that caught real bugs: sham co-inflation and the public-ness leak audit."""
from __future__ import annotations
import math
import random
from collections import Counter
from typing import Callable, Dict, Hashable, List, Set, Tuple


def units(m: int) -> List[int]:
    return [x for x in range(1, m) if math.gcd(x, m) == 1]


def mutual_info(samples: List[Tuple[Hashable, Hashable]]) -> float:
    N = len(samples)
    px, py, pxy = Counter(), Counter(), Counter()
    for x, y in samples:
        px[x] += 1; py[y] += 1; pxy[(x, y)] += 1
    return sum(v / N * math.log2(v * N / (px[x] * py[y])) for (x, y), v in pxy.items())


def leak_audit(m: int, dial: Callable[[int, int], Hashable]) -> float:
    """Bits the dial carries about the target a.  Nonzero => the dial is not computable from N."""
    G = units(m)
    return mutual_info([(a, dial(a, b)) for a in G for b in G])


def coinflation_check(m: int, K: Dict[int, Set[int]], seed: int = 0) -> Tuple[int, int, int]:
    """Unpriced-test cost on successful runs for K and for a same-size sham, plus the formula."""
    rng = random.Random(seed)
    G = units(m)
    sham = {c: set(rng.sample(G, len(K[c]))) for c in G}
    def buggy(P: Dict[int, Set[int]]) -> int:
        tot = 0
        for a in G:
            for b in G:
                c = (a * b) % m
                if a in P[c]:
                    tot += sum(1 for x in P[c] if x <= a)
        return tot
    formula = sum(len(K[c]) * (len(K[c]) + 1) for c in G) // 2
    return buggy(K), buggy(sham), formula


if __name__ == "__main__":
    m = 21
    print("public dial  c mod 3 :", round(leak_audit(m, lambda a, b: (a * b) % m % 3), 6), "bits")
    print("buggy dial   a mod 3 :", round(leak_audit(m, lambda a, b: a % 3), 6), "bits  <- not public")
    G = units(m)
    K = {c: set(G[: 1 + c % 5]) for c in G}
    print("co-inflation (real, sham, formula):", coinflation_check(m, K))
